import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('svc-deploy', 'deploy@corp.internal', 'service', 'sk-deploy-1a2b3c4d', 'platform')")
    db.commit()
    db.close()

@app.before_request
def check_api_key():
    key = request.headers.get('X-API-Key')
    if not key:
        # Allow unauthenticated access to health endpoint
        if request.path == '/health':
            return None
        return jsonify({'error': 'missing api key'}), 401
    # Validate key exists in database
    db = get_db()
    row = db.execute('SELECT username, role FROM users WHERE api_key = ?', (key,)).fetchone()
    if not row:
        return jsonify({'error': 'invalid api key'}), 403
    request.authenticated_user = row['username']
    request.user_role = row['role']

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/users/search')
def search_users():
    """Search users by department. Supports partial matching."""
    dept = request.args.get('department', '')
    sort_by = request.args.get('sort', 'username')

    # Whitelist sort columns to prevent injection there
    allowed_sorts = ['username', 'email', 'department', 'role']
    if sort_by not in allowed_sorts:
        sort_by = 'username'

    # Build query - department filter uses LIKE for partial match
    query = f"SELECT username, email, department, role FROM users WHERE department LIKE '%{dept}%' ORDER BY {sort_by}"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v1/users/<username>/profile')
def get_profile(username):
    """Get user profile. Non-admin users can only view their own."""
    if request.user_role != 'admin' and request.authenticated_user != username:
        return jsonify({'error': 'forbidden'}), 403
    db = get_db()
    row = db.execute('SELECT username, email, department, role FROM users WHERE username = ?', (username,)).fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(row))

@app.route('/api/v1/admin/export')
def admin_export():
    """Export all user data. Admin only."""
    if request.user_role != 'admin':
        return jsonify({'error': 'admin required'}), 403
    db = get_db()
    results = db.execute('SELECT username, email, department, role FROM users').fetchall()
    return jsonify({'export': [dict(r) for r in results]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
